input.newString:
@media(max-width:380px){.intro-row h1{font-size:30px}.intro-copy{font-size:9px;max-width:105px}.prompt-row label{max-width:76px;white-space:normal}.forge-button{font-size:7px}.range-message{display:none}.range-hud{justify-content:space-between}.range-instructions{font-size:7px}}

/* Three-dimensional first-person range */
.range-board{position:relative;isolation:isolate}
.fps-viewport{position:absolute;inset:48px 0 28px;overflow:hidden;background:#252b2b;cursor:crosshair;touch-action:none}
#fpsCanvas{position:absolute;inset:0;display:block;width:100%;height:100%;outline:0}
.range-board #rangeCanvas{display:none}
.fps-viewport.is-playing{cursor:none}
.fps-viewport.is-reloading #fpsCanvas{animation:reloadDip .85s ease-in-out}
@keyframes reloadDip{0%,100%{transform:translateY(0)}35%{transform:translateY(8px)}70%{transform:translateY(-3px)}}
.fps-welcome{position:absolute;inset:0;z-index:4;display:none;align-items:center;justify-content:center;padding:16px;background:rgba(9,12,11,.58);backdrop-filter:blur(3px)}
.fps-welcome.show{display:flex}
.fps-welcome-card{width:min(360px,100%);display:flex;flex-direction:column;align-items:center;padding:20px 24px 18px;border:1px solid #676951;background:rgba(18,21,18,.94);box-shadow:0 12px 45px #0008;text-align:center}
.overlay-stamp{font:8px var(--mono);letter-spacing:.16em;color:var(--acid)}
.overlay-sigil{margin:8px 0 3px;color:var(--acid);font-size:25px;line-height:1}
.fps-welcome-card>b{font:700 14px var(--mono);letter-spacing:.11em}
.fps-welcome-card>small{margin-top:7px;color:#b8b8a9;font-size:10px}
.fps-welcome-card button{margin-top:14px;padding:10px 15px;border:1px solid var(--acid);background:var(--acid);color:#171912;font:700 9px var(--mono);letter-spacing:.08em;cursor:pointer}
.fps-welcome-card button span{margin-left:10px;font-size:13px}
.fps-welcome-card .welcome-note{font-size:8px;color:#85877b}
.range-overlay{z-index:5}
@media(max-width:740px){.fps-viewport{inset:43px 0 25px}.fps-welcome-card{padding:15px 16px}.fps-welcome-card>b{font-size:12px}.fps-welcome-card>small{font-size:9px}}

