62:   function proceduralTexture(base, fleck, seed = 1) {
63:     const c = document.createElement('canvas'); c.width = c.height = 256;
64:     const g = c.getContext('2d'); g.fillStyle = base; g.fillRect(0, 0, 256, 256);
65:     let n = seed;
66:     const rand = () => { n = (n * 1664525 + 1013904223) >>> 0; return n / 4294967296; };
67:     for (let i = 0; i < 1800; i++) {
68:       g.globalAlpha = rand() * 0.22;
69:       g.fillStyle = fleck;
70:       const x = rand() * 256, y = rand() * 256, s = 1 + rand() * 3;
71:       g.fillRect(x, y, s, s);
72:     }
73:     g.globalAlpha = 1;
74:     const texture = new THREE.CanvasTexture(c);
75:     texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
76:     texture.colorSpace = THREE.SRGBColorSpace;
77:     return texture;
78:   }
