147:     board.position.set(0, 1.55, 0); board.castShadow = true; board.receiveShadow = true; board.userData.target = group; group.add(board);
148:     const circle = cylinder(group, .31, .31, .012, [0, 1.58, .036], materials.targetInk, 48, [Math.PI / 2, 0, 0]); circle.userData.target = group;
149:     const ring1 = cylinder(group, .225, .225, .014, [0, 1.58, .047], materials.paper, 48, [Math.PI / 2, 0, 0]); ring1.userData.target = group;
150:     const ring2 = cylinder(group, .145, .145, .016, [0, 1.58, .058], materials.targetRed, 48, [Math.PI / 2, 0, 0]); ring2.userData.target = group;
151:     const bull = cylinder(group, .06, .06, .018, [0, 1.58, .071], materials.paper, 32, [Math.PI / 2, 0, 0]); bull.userData.target = group;
152:     const outer = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(.72, 1.02, .055)), new THREE.LineBasicMaterial({ color: '#79786d' }));
153:     outer.position.copy(board.position); group.add(outer);
