251:   function noiseBurst(ctx, time, duration, cutoff, gain, decay = 8) {
252:     const length = Math.max(1, Math.floor(ctx.sampleRate * duration));
253:     const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
254:     const data = buffer.getChannelData(0);
255:     for (let i = 0; i < length; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
256:     const source = ctx.createBufferSource(); source.buffer = buffer;
257:     const filter = ctx.createBiquadFilter(); filter.type = 'highpass'; filter.frequency.value = cutoff;
258:     const volume = ctx.createGain(); volume.gain.setValueAtTime(gain, time); volume.gain.exponentialRampToValueAtTime(.001, time + duration);
259:     source.connect(filter).connect(volume).connect(ctx.destination); source.start(time);
260:   }
