262:   function shotSound() {
263:     if (!soundOn) return;
264:     const ctx = audio(), now = ctx.currentTime;
265:     // A designed arcade report: sharp broadband crack, low pressure thump, and short indoor reflection.
266:     noiseBurst(ctx, now, .11, 850, .72, 4.5);
267:     noiseBurst(ctx, now + .012, .2, 110, .42, 3.2);
268:     const thump = ctx.createOscillator(), envelope = ctx.createGain();
269:     thump.type = 'sine'; thump.frequency.setValueAtTime(105 + Math.random() * 22, now);
270:     thump.frequency.exponentialRampToValueAtTime(38, now + .16);
271:     envelope.gain.setValueAtTime(.48, now); envelope.gain.exponentialRampToValueAtTime(.001, now + .19);
272:     thump.connect(envelope).connect(ctx.destination); thump.start(now); thump.stop(now + .2);
273:     noiseBurst(ctx, now + .095, .22, 380, .12, 5.5);
274:   }
