276:   function mechanicalSound(kind = 'click') {
277:     if (!soundOn) return;
278:     const ctx = audio(), now = ctx.currentTime;
279:     noiseBurst(ctx, now, kind === 'rack' ? .13 : .045, kind === 'rack' ? 350 : 900, kind === 'rack' ? .22 : .16, 6);
280:     const osc = ctx.createOscillator(), gain = ctx.createGain();
281:     osc.type = 'triangle'; osc.frequency.setValueAtTime(kind === 'rack' ? 155 : 260, now);
282:     osc.frequency.exponentialRampToValueAtTime(65, now + .07);
283:     gain.gain.setValueAtTime(.13, now); gain.gain.exponentialRampToValueAtTime(.001, now + .08);
284:     osc.connect(gain).connect(ctx.destination); osc.start(now); osc.stop(now + .09);
285:   }
