301:   function hitTest() {
302:     raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);
303:     const active = targets.filter(t => t.userData.active).flatMap(t => t.userData.hitMeshes);
304:     const hit = raycaster.intersectObjects(active, false)[0];
305:     if (!hit) { say('MISS · CHECK YOUR SIGHT PICTURE'); return; }
306:     const target = hit.object.userData.target;
307:     const local = target.worldToLocal(hit.point.clone());
308:     const radius = Math.hypot(local.x, local.y - 1.58);
309:     const points = radius < .065 ? 100 : radius < .16 ? 50 : radius < .25 ? 25 : 10;
310:     target.userData.active = false; target.userData.respawn = performance.now() + 1150;
311:     target.userData.points = points; target.userData.board.material = mat('#8d6856', .92);
312:     score += points; updateHud();
313:     if (score > best) { best = score; localStorage.setItem('cursedBest', String(best)); $('#bestScore').textContent = `BEST: ${String(best).padStart(4, '0')}`; }
314:     lastHit = performance.now(); say(`PAPER HIT · +${points} · ${radius < .065 ? 'CENTER RING' : 'SCORE RECORDED'}`);
315:     mechanicalSound('click');
316:   }
