318:   function fire() {
319:     if (!equipped || !document.pointerLockElement || reloading) return;
320:     const now = performance.now();
321:     if (now - lastShot < Math.max(120, 650 - equipped.fire * 4)) return;
322:     lastShot = now;
323:     if (ammo <= 0) { say('EMPTY · PRESS R TO RELOAD'); mechanicalSound('click'); return; }
324:     ammo--; updateHud(); shotSound(); recoil = Math.min(.13, recoil + .075); muzzleTime = now + 55;
325:     hitTest();
326:     if (ammo === 0) setTimeout(() => { if (!ammo) say('EMPTY · PRESS R TO RELOAD'); }, 500);
327:   }
