342:   function onKeyDown(event) {
343:     if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.code) && document.pointerLockElement) event.preventDefault();
344:     keys.add(event.code);
345:     if (event.code === 'KeyR' && !event.repeat) beginReload();
346:     if (event.code === 'Space' && !event.repeat) fire();
347:   }
