351:   function updateMovement(dt) {
352:     if (!document.pointerLockElement) return;
353:     const speed = keys.has('ShiftLeft') ? 1.65 : 3.1;
354:     const forward = Number(keys.has('KeyW') || keys.has('ArrowUp')) - Number(keys.has('KeyS') || keys.has('ArrowDown'));
355:     const side = Number(keys.has('KeyD') || keys.has('ArrowRight')) - Number(keys.has('KeyA') || keys.has('ArrowLeft'));
356:     const length = Math.hypot(forward, side) || 1;
357:     const dx = (Math.sin(yaw) * forward + Math.cos(yaw) * side) * speed * dt / length;
358:     const dz = (-Math.cos(yaw) * forward + Math.sin(yaw) * side) * speed * dt / length;
359:     camera.position.x = THREE.MathUtils.clamp(camera.position.x + dx, -8.1, 8.1);
360:     camera.position.z = THREE.MathUtils.clamp(camera.position.z + dz, -1.1, 9.2);
361:     if (forward || side) bobTime += dt * (keys.has('ShiftLeft') ? 11 : 8);
362:   }
363: 
364:   function animate() {
365:     requestAnimationFrame(animate);
366:     const dt = Math.min(clock.getDelta(), .04), now = performance.now();
367:     updateMovement(dt);
368:     for (const target of targets) {
369:       target.position.x = target.userData.homeX + Math.sin(now * .00045 + target.userData.phase) * .34;
370:       if (!target.userData.active && now >= target.userData.respawn) {
371:         target.userData.active = true; target.userData.board.material = materials.paper;
372:       }
373:       target.visible = target.userData.active;
374:     }
375:     recoil = Math.max(0, recoil - dt * .48);
376:     if (weaponGroup) {
377:       const moving = document.pointerLockElement && (keys.has('KeyW') || keys.has('KeyA') || keys.has('KeyS') || keys.has('KeyD'));
378:       weaponGroup.position.y = -.31 + (moving ? Math.sin(bobTime) * .009 : Math.sin(now * .0017) * .002) - recoil * .38;
379:       weaponGroup.position.x = .32 + (moving ? Math.cos(bobTime * .5) * .008 : 0);
380:       weaponGroup.rotation.x = recoil * 1.9;
381:       const flash = now < muzzleTime;
382:       muzzleFlash.visible = flash;
383:       muzzleLight.intensity = flash ? 3.5 : 0;
384:       if (flash) muzzleFlash.scale.setScalar(.8 + Math.random() * .8);
385:     }
386:     if (reloading && magazine) magazine.position.y = -.27 - Math.sin(Math.min(1, (now % 850) / 850 * Math.PI) * Math.PI) * .12;
387:     renderer.render(scene, camera);
388:   }
